#{title}, #{businessType}, #{method}, #{requestMethod}, #{operatorType}, #{operName}, #{deptName}, #{operUrl}, #{operIp}, #{operLocation}, #{operParam}, #{jsonResult}, #{status}, #{errorMsg}, #{operTime}, #{createBy}, #{createTime}, #{traceId},

mapper.select:
select oper_id, title, business_type, method, request_method, operator_type, oper_name, dept_name, oper_url, oper_ip, oper_location, oper_param, json_result, status, error_msg, oper_time
from sys_oper_log_${operMonth}


        AND oper_id = #{operId}


        AND title like CONCAT(CONCAT('%', #{title}),'%')


        AND business_type = #{businessType}


        AND business_type in

            #{businessType}



        AND status = #{status}


        AND oper_name like CONCAT(CONCAT('%', #{operName}),'%')


        AND oper_param like CONCAT(CONCAT('%', #{operParam}),'%')


        AND oper_time >= STR_TO_DATE(CONCAT(#{beginTime}, ' 00:00:00'),'%Y-%m-%d %H:%i:%s %T')


        AND oper_time <= STR_TO_DATE(CONCAT(#{endTime}, ' 23:59:59'),'%Y-%m-%d %H:%i:%s %T')


order by oper_time desc

